import gurobipy as gp
from gurobipy import GRB
capacities = {}
products = {}
weights = {}
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('capacity.csv'):
        sid = rec['values']['StorageID']
        cap = int(rec['values']['Capacity'])
        capacities[sid] = cap
    elif rec['source'].endswith('products.csv'):
        pname = rec['values']['ProductName']
        val = int(rec['values']['Value'])
        wt = int(rec['values']['Weight'])
        products[pname] = val
        weights[pname] = wt
storage_ids = list(capacities.keys())
product_names = list(products.keys())
if len(storage_ids) == 0 or len(product_names) == 0:
    raise ValueError('Missing storage IDs or product names.')
for sid in storage_ids:
    if sid not in capacities:
        raise ValueError(f'Missing capacity for storage {sid}.')
for pname in product_names:
    if pname not in products or pname not in weights:
        raise ValueError(f'Missing value or weight for product {pname}.')
m = gp.Model('Amazon_AC_Storage')
x_vars = m.addVars(storage_ids, product_names, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((products[pname] * x_vars[sid, pname] for sid in storage_ids for pname in product_names)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((weights[pname] * x_vars[sid, pname] for pname in product_names)) <= capacities[sid] for sid in storage_ids), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
